// ── Minimal Subject/Observer skeleton (class-based) ─────────────
class Subject {
  constructor() {
    this._observers = [];
  }

  subscribe(obs) {
    this._observers.push(obs);
  }

  unsubscribe(obs) {
    this._observers = this._observers.filter(o => o !== obs);
  }

  notify(data) {
    // iterate a snapshot in case an observer unsubscribes during iteration
    [...this._observers].forEach(o => o.update(data));
  }
}

// ── ConcreteSubject ───────────────────────────────────────────────
class TemperatureSensor extends Subject {
  constructor() {
    super();
    this._temp = 0;
  }

  setTemperature(temp) {
    this._temp = temp;
    console.log(`[Sensor] temperature set to ${temp}°C`);
    this.notify({ temp: this._temp });
  }
}

// ── ConcreteObservers ────────────────────────────────────────────
class OverheatAlarm {
  update({ temp }) {
    if (temp > 80) console.log(`  [ALARM] CRITICAL: ${temp}°C — shutting down!`);
    else           console.log(`  [Alarm] ${temp}°C — within safe range`);
  }
}

class DataLogger {
  constructor() { this._log = []; }
  update({ temp }) {
    this._log.push({ temp, time: Date.now() });
    console.log(`  [Logger] recorded ${temp}°C (${this._log.length} entries)`);
  }
}

class DashboardWidget {
  update({ temp }) {
    console.log(`  [Dashboard] rendering thermometer at ${temp}°C`);
  }
}

// ── Wiring ───────────────────────────────────────────────────────
const sensor    = new TemperatureSensor();
const alarm     = new OverheatAlarm();
const logger    = new DataLogger();
const dashboard = new DashboardWidget();

sensor.subscribe(alarm);
sensor.subscribe(logger);
sensor.subscribe(dashboard);

sensor.setTemperature(65);
// [Sensor] temperature set to 65°C
//   [Alarm] 65°C — within safe range
//   [Logger] recorded 65°C (1 entries)
//   [Dashboard] rendering thermometer at 65°C

sensor.unsubscribe(dashboard); // user closes the dashboard

sensor.setTemperature(95);
// [Sensor] temperature set to 95°C
//   [ALARM] CRITICAL: 95°C — shutting down!
//   [Logger] recorded 95°C (2 entries)
// (dashboard NOT called — correctly unsubscribed)

// ── Production-style EventEmitter (named events) ─────────────────
class EventEmitter {
  constructor() {
    this._listeners = Object.create(null);
  }

  on(event, fn) {
    if (!this._listeners[event]) this._listeners[event] = [];
    this._listeners[event].push(fn);
    // return an unsubscribe handle — same pattern as Redux store.subscribe
    return () => this.off(event, fn);
  }

  once(event, fn) {
    const wrapper = (data) => { fn(data); this.off(event, wrapper); };
    return this.on(event, wrapper);
  }

  off(event, fn) {
    if (!this._listeners[event]) return;
    this._listeners[event] = this._listeners[event].filter(l => l !== fn);
  }

  emit(event, data) {
    // snapshot in case a listener calls off() during emit
    const fns = [...(this._listeners[event] || [])];
    fns.forEach(fn => fn(data));
  }
}

// ── ConcreteSubject: an order store ─────────────────────────────
class OrderStore extends EventEmitter {
  constructor() {
    super();
    this._orders = [];
  }

  addOrder(order) {
    this._orders.push(order);
    this.emit('order:added', order);
    if (this._orders.length % 100 === 0) {
      this.emit('milestone:reached', { count: this._orders.length });
    }
  }

  cancelOrder(id) {
    this._orders = this._orders.filter(o => o.id !== id);
    this.emit('order:cancelled', { id });
  }
}

// ── Observers as plain functions ─────────────────────────────────
const store = new OrderStore();

const unsubChart = store.on('order:added', (order) => {
  console.log(`[Chart] new order from ${order.customer} — $${order.total}`);
});

const unsubBadge = store.on('order:added', (order) => {
  console.log(`[Badge] +1 → total ${store._orders.length} orders`);
});

store.once('milestone:reached', ({ count }) => {
  console.log(`[Confetti] milestone: ${count} orders!`);
  // auto-removed after first fire — no memory leak
});

store.on('order:cancelled', ({ id }) => {
  console.log(`[Log] order ${id} cancelled`);
});

store.addOrder({ id: 1, customer: 'Alice', total: 49.99 });
// [Chart] new order from Alice — $49.99
// [Badge] +1 → total 1 orders

unsubBadge(); // user collapses the badge panel

store.addOrder({ id: 2, customer: 'Bob', total: 129.00 });
// [Chart] new order from Bob — $129
// (Badge observer silently gone)

store.cancelOrder(1);
// [Log] order 1 cancelled

sections.content:
Standard Observer pattern is **synchronous**: `notify()` calls each `update()` in sequence before returning. This is simple and predictable — by the time `setState()` returns, all observers have already executed. But it can cause performance problems if observers are expensive (repainting the DOM, running heavy calculations), and it can cause re-entrancy bugs if an observer triggers another state change on the same subject.

**Async notification** defers observer calls using `setTimeout`, `queueMicrotask`, or a scheduler:

```js
notify(data) {
  queueMicrotask(() => {
    [...this._observers].forEach(o => o.update(data));
  });
}
```

This batches multiple rapid state changes into fewer notification rounds (like React's batched updates in 18+). The tradeoff: observers no longer see state synchronously, which can complicate testing.

**RxJS and reactive streams** generalise this further. Instead of a single `update(data)` call, they model the stream of notifications as a first-class object (an `Observable`). Observers subscribe to the stream and can apply operators (`filter`, `debounceTime`, `switchMap`) between the source and the handler. This is Observer pattern with a full operator pipeline — enormously powerful for complex async scenarios like autocomplete search boxes, real-time collaboration, or WebSocket streams.

**Redux** uses synchronous dispatch: every `store.dispatch(action)` runs the reducer synchronously, then notifies all subscribers synchronously. Middleware like `redux-thunk` adds async coordination on top, but the core Observer loop remains synchronous and predictable.

**Vue 3 / MobX** use a fine-grained reactive system: they track which computed values and effects depend on which reactive properties (automatic subscription), then schedule updates in a microtask queue. This is Observer pattern with automatic dependency tracking — you never call `subscribe` manually; the framework instruments property access to do it for you.

A **notification chain** occurs when an observer's `update()` method triggers another state change on a different (or the same) subject, which triggers another round of notifications. In small systems this is harmless. In large systems it creates cascading fan-out that is nearly impossible to trace in a debugger.

Example of a dangerous chain:
```js
class CartStore extends Subject {
  addItem(item) {
    this._items.push(item);
    this.notify(this._items);
  }
}

class PriceCalculator {
  update(items) {
    const total = items.reduce((s, i) => s + i.price, 0);
    priceStore.setTotal(total); // triggers ANOTHER notify chain!
  }
}

class TaxStore extends Subject {
  // observes priceStore and recomputes tax...
  // which triggers YET ANOTHER chain
}
```

This produces execution order that depends on subscription order, with state changing multiple times per user action. Bugs appear that only reproduce when components subscribe in a particular sequence.

**Solutions:**
- Keep observers **read-only** with respect to the subject graph. Observers should update UI or fire external side effects, not mutate other observable state.
- Use a **command bus or event bus** that collects all state changes from a single user action and processes them in one batch before notifying observers.
- Apply **unidirectional data flow** (the Flux/Redux architecture): actions → reducer → new state → notify. No observer is allowed to dispatch another action during a dispatch cycle — Redux enforces this explicitly and throws if you try.
- In RxJS, avoid `subscribe` callbacks that call `next` on another Subject; prefer composing operators in the pipeline instead.

