// ── TypeScript: typed Observable with generics ───────────────────
type Handler<T> = (data: T) => void;

class TypedEmitter<Events extends Record<string, unknown>> {
  private listeners = {} as { [K in keyof Events]?: Array<Handler<Events[K]>> };

  on<K extends keyof Events>(event: K, fn: Handler<Events[K]>): () => void {
    if (!this.listeners[event]) this.listeners[event] = [];
    this.listeners[event]!.push(fn);
    return () => this.off(event, fn);
  }

  off<K extends keyof Events>(event: K, fn: Handler<Events[K]>): void {
    const list = this.listeners[event];
    if (list) this.listeners[event] = list.filter(l => l !== fn) as typeof list;
  }

  emit<K extends keyof Events>(event: K, data: Events[K]): void {
    [...(this.listeners[event] || [])].forEach(fn => fn(data));
  }
}

// ── Typed event map ───────────────────────────────────────────────
type StoreEvents = {
  'order:added':     { id: number; customer: string; total: number };
  'order:cancelled': { id: number };
  'stock:low':       { sku: string; remaining: number };
};

const store = new TypedEmitter<StoreEvents>();

// TypeScript enforces the payload shape at compile time
const unsub = store.on('order:added', ({ id, customer, total }) => {
  console.log(`New order #${id} from ${customer}: $${total}`);
});

store.emit('order:added', { id: 42, customer: 'Alice', total: 99.99 });
// New order #42 from Alice: $99.99

store.emit('order:added', { id: 43, customer: 'Bob', total: 14.50 });
// New order #43 from Bob: $14.5

unsub(); // clean up before end of scope

// TypeScript will catch mismatches at compile time:
// store.emit('order:added', { id: 'bad', customer: 123 }); // TS error!
// store.on('unknown:event', fn); // TS error!
